#include <string.h>
bool matrix_parse(matrix *m, const char *t) {
    (void)t;
    m->rows = m->cols = 0;
    m->values = NULL;
    return false;
}
size_t matrix_row(const matrix *m, size_t i, int *o) {
    (void)m;
    (void)i;
    (void)o;
    return 0;
}
size_t matrix_column(const matrix *m, size_t i, int *o) { return matrix_row(m, i, o); }
void matrix_free(matrix *m) { free(m->values); }

