solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
bool matrix_parse(matrix *m, const char *t) {
    m->rows = 0;
    m->cols = 0;
    m->values = NULL;
    size_t cap = 16, n = 0, row = 0;
    int *v = (int *)malloc(cap * sizeof(int));
    const char *p = t;
    while (*p) {
        if (*p == '\n') {
            if (!row || (m->cols && row != m->cols)) {
                free(v);
                return false;
            }
            m->cols = row;
            row = 0;
            m->rows++;
            p++;
            continue;
        }
        if (isspace((unsigned char)*p)) {
            p++;
            continue;
        }
        char *end;
        long x = strtol(p, &end, 10);
        if (p == end) {
            free(v);
            return false;
        }
        if (n == cap) {
            cap *= 2;
            v = (int *)realloc(v, cap * sizeof(int));
        }
        v[n++] = (int)x;
        row++;
        p = end;
    }
    if (row) {
        if (m->cols && row != m->cols) {
            free(v);
            return false;
        }
        m->cols = row;
        m->rows++;
    }
    m->values = v;
    return true;
}
size_t matrix_row(const matrix *m, size_t i, int *out) {
    if (!i || i > m->rows)
        return 0;
    memcpy(out, m->values + (i - 1) * m->cols, m->cols * sizeof(int));
    return m->cols;
}
size_t matrix_column(const matrix *m, size_t i, int *out) {
    if (!i || i > m->cols)
        return 0;
    for (size_t r = 0; r < m->rows; r++)
        out[r] = m->values[r * m->cols + i - 1];
    return m->rows;
}
void matrix_free(matrix *m) {
    free(m->values);
    m->values = NULL;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    matrix m;
    int o[10];
    assert(matrix_parse(&m, "1 2 3\n4 5 6"));
    assert(matrix_row(&m, 2, o) == 3 && o[0] == 4 && o[2] == 6);
    assert(matrix_column(&m, 2, o) == 2 && o[0] == 2 && o[1] == 5);
    assert(matrix_column(&m, 4, o) == 0);
    matrix_free(&m);
    assert(!matrix_parse(&m, "1 2\n3"));

    return 0;
}
